package parser

import (
	"fmt"
	"testing"
)

type portedParserErrorCase struct {
	language string
	source   string
	line     int
	method   string
	input    string
	wantID   string
}

func TestPortedParserErrorAssertions(t *testing.T) {
	for _, tt := range portedParserErrorCases {
		t.Run(fmt.Sprintf("%s:%d/%s", tt.source, tt.line, tt.method), func(t *testing.T) {
			issues := parserForPortedErrorLanguage(tt.language).ParseErrors(tt.input)
			if len(issues) == 0 {
				t.Fatalf("ParseErrors(%q) returned no issues, want %s", tt.input, tt.wantID)
			}
			if got := issues[0].ID; got != tt.wantID {
				t.Fatalf("first issue ID = %q, want %q", got, tt.wantID)
			}
		})
	}
}

func parserForPortedErrorLanguage(language string) *Parser {
	switch language {
	case "less":
		return NewLESSParser()
	case "scss":
		return NewSCSSParser()
	default:
		return NewParser()
	}
}

